// Get next order from processing queue and extract custom elements
// In production, this would query a database queue
// For now, we'll simulate getting an order from the previous workflow

const inputData = $input.first();
if (!inputData || !inputData.json) {
  console.log('No input data received');
  return [];
}

const orderData = inputData.json;

// Check if order is ready for AI generation
if (orderData.status !== 'queued_for_processing') {
  console.log(`Order ${orderData.amazonOrderId} not ready for processing. Status: ${orderData.status}`);
  return [];
}

// Extract and validate custom elements from characterSpecs
const characterSpecs = orderData.characterSpecs || {};
const customElements = {
  childName: characterSpecs.childName || 'Adventure Hero',
  skinTone: characterSpecs.skinTone || 'medium',
  hairColor: characterSpecs.hairColor || 'brown',
  hairStyle: characterSpecs.hairStyle || 'short/straight',
  age: parseInt(characterSpecs.age) || 5,
  pronouns: characterSpecs.pronouns || 'they/them',
  favoriteColor: characterSpecs.favoriteColor || 'blue',
  animalGuide: characterSpecs.animalGuide || 'dog',
  clothingStyle: characterSpecs.clothingStyle || 't-shirt and shorts'
};

// Update order status to processing with custom elements
const processingOrder = {
  ...orderData,
  characterSpecs: customElements,
  status: 'ai_generation_in_progress',
  aiGenerationStartedAt: new Date().toISOString(),
  posesGenerated: 0,
  totalPosesRequired: 12,
  generationProgress: 0
};

console.log(`Starting AI generation for order: ${orderData.amazonOrderId}`);
console.log(`Custom elements:`, customElements);
return [{ json: processingOrder }];

