// Generate Character Hash — EACH mode
// Deterministic, normalized hash from characterSpecs.
// IMPORTANT: In EACH mode, return a single object (not an array).

const j  = { ...($json || {}) };
const b  = $binary || {};
const cs = j.characterSpecs || {};

function intOr(v, d){ const n = Number.parseInt(v, 10); return Number.isFinite(n) ? n : d; }

// Create a normalized character specification object for hashing
const characterHashSpec = {
  skinTone:       (cs.skinTone || 'medium'),
  hairColor:      (cs.hairColor || 'brown'),
  hairStyle:      (cs.hairStyle || 'short/straight'),
  age:            intOr(cs.age, 5),
  pronouns:       (cs.pronouns || 'they/them'),
  favoriteColor:  (cs.favoriteColor || 'blue'),
  animalGuide:    (cs.animalGuide || 'dog'),
  clothingStyle:  (cs.clothingStyle || 't-shirt and shorts'),
};

// Order keys for stable hashing
const orderedSpec = Object.keys(characterHashSpec)
  .sort()
  .reduce((acc, k) => { acc[k] = characterHashSpec[k]; return acc; }, {});

// Generate a deterministic hash from the character specifications
const crypto = require('crypto');
const hashString = JSON.stringify(orderedSpec);
const characterHash = crypto.createHash('sha256').update(hashString).digest('hex').substring(0, 16);

// Add character hash and normalized specs to order data
const out = {
  ...j,
  characterSpecs: cs,             // preserve original specs
  characterHash,                  // short deterministic id
  characterHashSpec: orderedSpec, // normalized spec used for hashing
  characterPath: `characters/${characterHash}`,
  templatePath: 'templates',
};

// Optional: log for debug
console.log(`Generated character hash: ${characterHash}`);

// EACH mode => return a SINGLE object
return {
  json: out,
  binary: b,
  // preserve pairing if present (helps downstream merges)
  ...(($input && $input.item && $input.item.pairedItem) ? { pairedItem: $input.item.pairedItem } : {})
};

// Restore Metadata After Upload — EACH mode
// Merges the S3/R2 upload result (this item) back onto the original image context
// from "Process Gemini API response and extract generated image" (or equivalent extractor).
// Returns a SINGLE object (EACH mode).

const uploadJson = { ...($json || {}) };
const fallbackBin = $binary || {};
const runIx = (typeof $runIndex === 'number') ? $runIndex : 0;
const itemIx = (typeof $itemIndex === 'number') ? $itemIndex : 0;

// -------- helpers --------
function safeItems(nodeName, rIx) {
  try { return $items(nodeName, 0, rIx) || []; } catch { return []; }
}

// Try multiple likely extractor node names (handles base/pose variants)
const SOURCE_NODES = [
  'Process Gemini API response and extract generated image',
  'Extract Generated Image',
  'Extract Generated Image — Retry',
  'Extract BASE CHARACTER image from Gemini response — EACH mode',
];

function getFirstExistingSourceItem() {
  for (const name of SOURCE_NODES) {
    const arr = safeItems(name, runIx);
    if (!arr.length) continue;
    if (arr.length) {
      const picked = arr[itemIx] || arr[0];
      if (picked) return { item: picked, nodeName: name, runUsed: (arr === safeItems(name, runIx) ? runIx : 0) };
    }
  }
  return { item: null, nodeName: null, runUsed: null };
}

function pick(obj, keys = []) {
  for (const k of keys) {
    if (obj && obj[k] != null && obj[k] !== '') return obj[k];
  }
  return undefined;
}

// -------- locate original context --------
const { item: originalItem, nodeName: sourceNode, runUsed } = getFirstExistingSourceItem();
if (!originalItem || !originalItem.json) {
  throw new Error('Restore Metadata: could not locate original extractor item (check node name list or runs).');
}

const originalJson = originalItem.json || {};
const originalBin  = originalItem.binary || fallbackBin;

// Pull out a few common upload fields for convenience
const uploadedUrl = pick(uploadJson, ['url', 'fileUrl', 'publicUrl', 'Location', 'location', 'signedUrl']);
const uploadedKey = pick(uploadJson, ['key', 'fileKey', 's3Key', 'r2Key', 'Key']);

// -------- build merged json --------
const out = {
  ...originalJson,
  // surface helpful pointers if present (do not overwrite with undefined)
  ...(uploadedUrl ? { generatedUploadUrl: uploadedUrl } : {}),
  ...(uploadedKey ? { generatedUploadKey: uploadedKey } : {}),
  // keep the full upload payload under a namespaced key
  uploadResult: {
    ...(originalJson.uploadResult || {}),
    ...uploadJson,
  },
  __meta: {
    ...(originalJson.__meta || {}),
    restoreAfterUpload: {
      sourceNode: sourceNode || 'unknown',
      sourceRunIx: runUsed,
      itemIndex: itemIx,
      surfacedUrl: Boolean(uploadedUrl),
      surfacedKey: Boolean(uploadedKey),
    },
  },
};

// Binaries: keep the original item’s binaries (the upload result rarely carries any)
const binOut = originalBin || fallbackBin || {};

// -------- emit (EACH mode => single object) --------
return {
  json: out,
  binary: binOut,
  // Prefer the original pairing; else fall back to current
  pairedItem:
    (originalItem.pairedItem)
      ? originalItem.pairedItem
      : (($input && $input.item && $input.item.pairedItem) ? $input.item.pairedItem : { item: itemIx }),
};

// Extract BASE CHARACTER image from Gemini response — EACH mode
// Accepts tiny images in mock/test mode; enforces min size in production.

const root = $json || {};
const b = $binary || {};
const runIx = (typeof $runIndex === 'number') ? $runIndex : 0;
const itemIx = (typeof $itemIndex === 'number') ? $itemIndex : 0;

/* ---------- helpers ---------- */
function pickRoot(r){
  if (r?.body?.candidates) return r.body;
  if (r?.response?.candidates) return r.response;
  if (r?.data?.candidates) return r.data;
  return r;
}

function firstInlineFromParts(parts){
  if (!Array.isArray(parts)) return null;
  for (const p of parts){
    const id = p?.inlineData?.data || p?.inline_data?.data;
    if (id) {
      return {
        b64: String(id),
        mime: p?.inlineData?.mimeType || p?.inline_data?.mime_type || 'image/png',
        path: 'content.parts.inlineData'
      };
    }
  }
  return null;
}

function findInlineImage(r){
  const cand = r?.candidates?.[0];
  if (cand?.content?.parts){
    const got = firstInlineFromParts(cand.content.parts);
    if (got) return got;
  }
  if (Array.isArray(cand?.content) && cand.content[0]?.parts){
    const got = firstInlineFromParts(cand.content[0].parts);
    if (got) return got;
  }
  // Deep fallback
  const stack = [r];
  while (stack.length) {
    const cur = stack.pop();
    if (!cur || typeof cur !== 'object') continue;
    const d = cur?.inlineData?.data || cur?.inline_data?.data;
    if (d) {
      return {
        b64: String(d),
        mime: cur?.inlineData?.mimeType || cur?.inline_data?.mime_type || 'image/png',
        path: '...inlineData/inline_data (fallback)'
      };
    }
    for (const k of Object.keys(cur)) {
      const v = cur[k];
      if (v && typeof v === 'object') stack.push(v);
    }
  }
  return null;
}

function safeItems(nodeName, rIx){ try { return $items(nodeName, 0, rIx) || []; } catch { return []; } }
function getNodeItem(nodeName) {
  let arr = safeItems(nodeName, runIx);
  if (!arr.length) arr = safeItems(nodeName, 0);
  return arr[itemIx] || arr[0] || { json:{} };
}

/* ---------- extract ---------- */
const resp = pickRoot(root);
const hit  = findInlineImage(resp);

const finish = resp?.candidates?.[0]?.finishReason || resp?.promptFeedback || resp?.candidates?.[0]?.safetyRatings || null;
const finishBrief = (typeof finish === 'string') ? finish : JSON.stringify(finish || {}, null, 0).slice(0, 300);

// Detect mock/testing (your mock sets modelVersion to "...mock")
const modelVersion = resp?.modelVersion || root?.modelVersion || '';
const isMock = /mock/i.test(modelVersion) || root.__testMode === true || root.__allowTinyImage === true;

if (!hit || !hit.b64) {
  throw new Error(`No inline image in Gemini response. finishReason/safety: ${finishBrief || 'n/a'}`);
}

const buf  = Buffer.from(hit.b64, 'base64');
const mime = hit.mime || 'image/png';

// Enforce a minimum byte size in production; allow tiny images in mock.
const defaultMinBytes = 40; // PNG 1x1 often ~67 bytes; keep threshold conservative
const minBytes = Number.isFinite(Number(root.minImageBytes)) ? Number(root.minImageBytes) : defaultMinBytes;

if (!isMock && buf.length < minBytes) {
  throw new Error(`Inline image too small (${buf.length}B < ${minBytes}B). finishReason/safety: ${finishBrief || 'n/a'}`);
}

/* ---------- name & context ---------- */
const hashCtx = getNodeItem('Generate Character Hash').json || {};
const characterHash = root?.characterHash || hashCtx.characterHash || 'nohash';
const ext = (mime.split('/')[1] || 'png').toLowerCase();
const fileName = `characters_${characterHash}_base.${ext}`;

/* ---------- binary ---------- */
const genBin = await this.helpers.prepareBinaryData(buf, fileName, mime);
genBin.mimeType = mime;
genBin.fileExtension = ext;

/* ---------- emit (EACH: single object) ---------- */
return {
  json: {
    ...hashCtx,
    ...root,
    generatedImage: { mimeType: mime, size: buf.length, modelVersion, isMock },
    baseGeneratedFileName: fileName,
    __meta: {
      ...(root?.__meta || {}),
      generatedAttemptKey: fileName,
      sourcePath: hit.path,
      finishBrief,
      bindDebug: { runIx, itemIndex: itemIx }
    }
  },
  binary: { ...b, data: genBin },
  pairedItem: ($input && $input.item && $input.item.pairedItem) ? $input.item.pairedItem : { item: itemIx }
};

// Build Dynamic Hairstyle Description — EACH mode (place just BEFORE "Prepare Binary")
// Adds: json.hairPromptBlock and json.hairPromptMeta (incl. hairColorHex + hairColorLock + clothing lock)
// Preserves binaries and aliases first unknown key to `image` if needed.

const j  = { ...($json || {}) };
const b  = $binary || {};
const cs = j.characterSpecs || {};

/* ---------------- Utils (local, but prefer globals if present) ---------------- */
function norm(s){
  return String(s||'')
    .toLowerCase()
    .replace(/[^a-z0-9#+\s-]/g,' ')   // SAFE: hyphen at end, single backslashes
    .replace(/\s+/g,' ')
    .trim();
}

// If a Shared Utils node set global.canonicalClothingType, use it.
// Otherwise define a compatible local fallback.
const canonicalClothingType = (typeof global !== 'undefined' && typeof global.canonicalClothingType === 'function')
  ? global.canonicalClothingType
  : function canonicalClothingTypeLocal(raw){
      const s = norm(raw);
      if (!s) return 'tee-shorts';
      if (/dress|sundress|gown/.test(s)) return 'dress';
      // default → tee+shorts
      return 'tee-shorts';
    };

/* ---------------- Hair style canonicalization (your live 13) ---------------- */
const CANONICAL_STYLES = [
  'ponytail','pigtails',
  'straight-short','straight-medium','straight-long',
  'curly-short','curly-medium','curly-long',
  'afro','pom-poms','bun','locs','side-part'
];

function canonicalStyle(styleRaw) {
  const s = norm(styleRaw);
  if (!s) return 'generic';
  const sh = s.replace(/-/g,' ');
  if (/(^|\s)pom\s*poms?($|\s)|space\s*buns?|puffs?/.test(sh)) return 'pom-poms';
  if (/pigtails?/.test(sh)) return 'pigtails';
  if (/side\s*part/.test(sh)) return 'side-part';
  if (/(^|\s)bun($|\s)/.test(sh)) return 'bun';
  if (/(locs|dreadlocks|dreads)/.test(sh)) return 'locs';
  if (/afro/.test(sh)) return 'afro';
  if (/ponytail|pony\s*tail/.test(sh)) return 'ponytail';

  if (/straight/.test(sh) && /(short|above\s*chin|chin)/.test(sh)) return 'straight-short';
  if (/straight/.test(sh) && /(medium|shoulder|to\s*shoulders?)/.test(sh)) return 'straight-medium';
  if (/straight/.test(sh) && /(long|below\s*shoulders?)/.test(sh)) return 'straight-long';
  if (/straight/.test(sh)) return 'straight-medium';

  if (/(curly|curls)/.test(sh) && /(short|halo)/.test(sh)) return 'curly-short';
  if (/(curly|curls)/.test(sh) && /(medium|shoulder)/.test(sh)) return 'curly-medium';
  if (/(curly|curls)/.test(sh) && /(long|below\s*shoulders?)/.test(sh)) return 'curly-long';
  if (/(curly|curls)/.test(sh)) return 'curly-medium';

  return 'generic';
}

/* ---------------- Hair color canonicalization ---------------- */
// Customer-facing labels → fixed HEX (your palette)
const HAIR_COLOR_MAP = {
  'blonde':             { id:'blonde',            hex:'#D1B26F' },
  'strawberry blonde':  { id:'strawberry-blonde', hex:'#E6A273' },
  'light-brown':        { id:'light-brown',       hex:'#A4754A' },
  'medium-brown':       { id:'medium-brown',      hex:'#7B4B2A' },
  'dark-brown':         { id:'dark-brown',        hex:'#523418' },
  'auburn':             { id:'auburn',            hex:'#8B3F2C' },
  'black':              { id:'black',             hex:'#2B2B2B' },
  'red':                { id:'red',               hex:'#C25E2E' }
};

// Accept many synonyms and raw hex like "#734a2f"
function canonicalHairColor(raw){
  const s = norm(raw);
  if (!s) return { id:'unspecified', hex:null, source:'empty' };

  // direct hex pass-through
  const m = s.match(/#?[0-9a-f]{6}\b/i);
  if (m){
    const hex = ('#' + m[0].replace('#','')).toUpperCase();
    return { id:'custom-hex', hex, source:'hex' };
  }

  // normalize synonyms
  const table = [
    [/strawberry\s*blonde|strawberry-blonde|strawberryblonde|strawb.*blonde/, 'strawberry blonde'],
    [/light\s*brown|lt\s*brown|brown\s*light/, 'light-brown'],
    [/medium\s*brown|mid\s*brown|brown\s*medium/, 'medium-brown'],
    [/dark\s*brown|dk\s*brown|brown\s*dark/, 'dark-brown'],
    [/auburn|reddish\s*brown/, 'auburn'],
    [/ginger|copper|true\s*red/, 'red'],
    [/jet\s*black|black/, 'black'],
    [/blonde|blond/, 'blonde'],
  ];
  for (const [re,label] of table){
    if (re.test(s)) return { ...HAIR_COLOR_MAP[label], source:'label' };
  }

  if (HAIR_COLOR_MAP[s]) return { ...HAIR_COLOR_MAP[s], source:'label-exact' };
  return { id:'unspecified', hex:null, source:'unknown' };
}

const colorIn = cs.hairColor || j.hairPromptMeta?.color || '';
const colorCanon = canonicalHairColor(colorIn);

/* ---------------- Clothing type (now robust to style/type fields) ---------- */
const clothingTypeCanonical = canonicalClothingType(
  cs.clothingType ?? cs.clothingStyle ?? j.clothingType ?? j.clothingStyle ?? j.clothingTypeCanonical
) || 'tee-shorts';

/* ---------------- Prompt map (same styles; side-part stricter) -------------- */
const PROMPT_MAP = {
  'ponytail': [
    'HAIRSTYLE — PONYTAIL',
    colorCanon.hex ? `Hair color base: ${colorCanon.hex}` : 'Hair color: unspecified',
    '- Hair gathered into one ponytail; visible tie.',
    '- Tail sits behind head/neck; no loose strands on face/shoulders.',
    '- Tail reads as one connected mass.'
  ],
  'pigtails': [
    'HAIRSTYLE — PIGTAILS (TWO PONYTAILS)',
    colorCanon.hex ? `Hair color base: ${colorCanon.hex}` : 'Hair color: unspecified',
    '- Two mid-height ponytails with visible ties.',
    '- Tails near shoulders without covering face.',
    '- Each tail forms a closed silhouette; no flyaways.'
  ],
  'straight-short': [
    'HAIRSTYLE — STRAIGHT (SHORT / ABOVE CHIN)',
    colorCanon.hex ? `Hair color base: ${colorCanon.hex}` : 'Hair color: unspecified',
    '- Short straight cut above chin; eyes fully clear.',
    '- Silhouette hugs head; no stringy separated strands.'
  ],
  'straight-medium': [
    'HAIRSTYLE — STRAIGHT (MEDIUM / TO SHOULDERS)',
    colorCanon.hex ? `Hair color base: ${colorCanon.hex}` : 'Hair color: unspecified',
    '- Straight to shoulder length, falling behind shoulders.',
    '- Neat part; no strands across eyes/cheeks.'
  ],
  'straight-long': [
    'HAIRSTYLE — STRAIGHT (LONG / BELOW SHOULDERS)',
    colorCanon.hex ? `Hair color base: ${colorCanon.hex}` : 'Hair color: unspecified',
    '- Long straight hair past shoulders, kept behind back.',
    '- Minimal layering; tips not split/stringy.'
  ],
  'curly-short': [
    'HAIRSTYLE — CURLY (SHORT / HALO)',
    colorCanon.hex ? `Hair color base: ${colorCanon.hex}` : 'Hair color: unspecified',
    '- Compact curl halo close to head.',
    '- Suggest curls with interior shapes; outer contour continuous.'
  ],
  'curly-medium': [
    'HAIRSTYLE — CURLY (MEDIUM / TO SHOULDERS)',
    colorCanon.hex ? `Hair color base: ${colorCanon.hex}` : 'Hair color: unspecified',
    '- Medium curls to shoulder level.',
    '- Group curls so outer silhouette stays continuous.'
  ],
  'curly-long': [
    'HAIRSTYLE — CURLY (LONG / BELOW SHOULDERS)',
    colorCanon.hex ? `Hair color base: ${colorCanon.hex}` : 'Hair color: unspecified',
    '- Long curls falling behind shoulders/back.',
    '- Single connected outline; texture inside the shape.'
  ],
  'afro': [
    'HAIRSTYLE — AFRO (ROUNDED)',
    colorCanon.hex ? `Hair color base: ${colorCanon.hex}` : 'Hair color: unspecified',
    '- Even, rounded afro around the head.',
    '- Texture via tone; no pinholes to background.'
  ],
  'pom-poms': [
    'HAIRSTYLE — POM-POMS / SPACE BUNS (TWO PUFFS)',
    colorCanon.hex ? `Hair color base: ${colorCanon.hex}` : 'Hair color: unspecified',
    '- Two symmetric puffs high on upper sides/crown; clean center part; small ties.',
    '- SIZE: each ≤ 30% of head width; combined span ≤ 90%.',
    '- PLACEMENT: above and slightly behind ears; do not overlap face.'
